set -euo pipefail
mkdir -p "$FIXTURE_BIN"
case "${BROWSER_PACKAGE:-google-chrome-stable}" in
  google-chrome-stable) fixture_browser=google-chrome ;;
  chromium) fixture_browser=chromium ;;
  *) exit 97 ;;
esac
cat >"$FIXTURE_BIN/$fixture_browser" <<'BROWSER'
#!/bin/sh
test "$1" = --version || exit 97
test "${BROWSER_BROKEN:-0}" = 0 || exit 1
printf 'Google Chrome fixture\n'
BROWSER
chmod +x "$FIXTURE_BIN/$fixture_browser"
export PATH="$FIXTURE_BIN:/usr/bin:/bin"
dpkg-query() {
  test "$3" != "${MISSING_PACKAGE:-}" || return 1
  case "$3" in
    google-chrome-stable|chromium|chromium-browser)
      test "$3" = "${BROWSER_PACKAGE:-google-chrome-stable}" || return 1 ;;
  esac
  if test "$3" = "${BROKEN_PACKAGE:-}"; then
    printf 'deinstall ok config-files'
  elif test "$3" = "${HELD_PACKAGE:-}"; then
    printf 'hold ok installed'
  else
    printf 'install ok installed'
  fi
}
apt-get() {
  printf 'apt-get %s\n' "$*" >>"$FIXTURE_LOG"
  test "${INSTALL_ALLOWED:-0}" = 1 || return 99
  case " $* " in *" update "*) return 0 ;; esac
  test "${INSTALL_FAIL:-0}" = 0 || return 47
}
curl() { printf 'network forbidden\n' >>"$FIXTURE_LOG"; return 98; }
retry() { "$@"; }
systemctl() { return 0; }
timeout() { shift; "$@"; }

sleep() { :; }

package localcontainer

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestBrowserBootstrapPackageSelection(t *testing.T) {
	const fingerprint = "35BAA0B33E9EB396F59CA838C0BA5CE6DC6315A3"
	for _, tc := range []struct {
		name, distro, working, available, broken, failure string
		wantInstall, wantError                            string
	}{
		{name: "working Chrome untouched", distro: "ubuntu", working: "google-chrome"},
		{name: "working Chromium untouched", distro: "ubuntu", working: "chromium"},
		{name: "working ESR untouched", distro: "ubuntu", working: "firefox-esr"},
		{name: "working Firefox untouched", distro: "ubuntu", working: "firefox"},
		{name: "Ubuntu native Firefox", distro: "ubuntu", available: "firefox", wantInstall: "firefox/mozilla"},
		{name: "Ubuntu broken Chromium advances", distro: "ubuntu", available: "chromium firefox", broken: "chromium", wantInstall: "firefox/mozilla"},
		{name: "Debian Chromium", distro: "debian", available: "chromium firefox-esr", wantInstall: "chromium"},
		{name: "Debian broken Chromium advances", distro: "debian", available: "chromium firefox-esr", broken: "chromium", wantInstall: "firefox-esr"},
		{name: "Debian broken ESR advances", distro: "debian", available: "firefox-esr firefox", broken: "firefox-esr", wantInstall: "firefox"},
		{name: "Mozilla wrong key", distro: "ubuntu", available: "firefox", failure: "key", wantError: "signing key"},
		{name: "Mozilla metadata unavailable", distro: "ubuntu", available: "firefox", failure: "metadata", wantError: "Mozilla Firefox"},
		{name: "installed transition cannot downgrade", distro: "ubuntu", available: "firefox", failure: "install", wantError: "Mozilla Firefox"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			root := t.TempDir()
			bin := filepath.Join(root, "bin")
			if err := os.Mkdir(bin, 0o755); err != nil {
				t.Fatal(err)
			}
			write := func(name, content string) {
				t.Helper()
				if err := os.WriteFile(name, []byte(content), 0o755); err != nil {
					t.Fatal(err)
				}
			}
			write(filepath.Join(root, "os-release"), "ID="+tc.distro+"\n")
			for _, browser := range []string{"google-chrome", "chromium", "firefox-esr", "firefox"} {
				write(filepath.Join(bin, browser), "#!/bin/sh\n[ -f \"$TEST_ROOT/working-"+browser+"\" ]\n")
			}
			if tc.working != "" {
				write(filepath.Join(root, "working-"+tc.working), "original\n")
			}
			write(filepath.Join(bin, "dpkg"), "#!/bin/sh\nprintf 'arm64\\n'\n")
			write(filepath.Join(bin, "curl"), "#!/bin/sh\nprintf 'fixture public key\\n'\n")
			write(filepath.Join(bin, "gpg"), `#!/bin/sh
case "$*" in
  *--fingerprint*) printf 'fpr:::::::::%s:\n' "$TEST_FINGERPRINT" ;;
  *--export*) printf 'fixture verified keyring\n' ;;
esac
`)
			write(filepath.Join(bin, "apt-cache"), `#!/bin/sh
case " $TEST_AVAILABLE " in *" $2 "*) exit 0 ;; esac
exit 100
`)
			write(filepath.Join(bin, "apt-get"), `#!/bin/sh
set -eu
printf '%s\n' "$*" >> "$TEST_ROOT/apt-calls"
case "$*" in
  *update*)
    if [ "$TEST_FAILURE" = metadata ] && [ -f "$TEST_ROOT/apt/sources.list.d/crabbox-mozilla.sources" ]; then exit 100; fi
    exit 0 ;;
esac
for package in "$@"; do
  case "$package" in
    firefox/mozilla)
      [ "$TEST_FAILURE" != install ] || exit 100
      [ -s "$TEST_ROOT/apt/keyrings/crabbox-mozilla.gpg" ] || exit 99
      printf 'installed\n' > "$TEST_ROOT/working-firefox"
      exit 0 ;;
    chromium|firefox-esr|firefox)
      if [ "$TEST_DISTRO" = ubuntu ] && [ "$package" = firefox ]; then
        printf 'Snap transition attempted\n' >> "$TEST_ROOT/snap-attempt"
        exit 100
      fi
      case " $TEST_BROKEN " in *" $package "*) exit 100 ;; esac
      printf 'installed\n' > "$TEST_ROOT/working-$package"
      exit 0 ;;
  esac
done
`)
			start := strings.Index(bootstrapScript, `if [ "${CRABBOX_BROWSER:-0}" = "1" ] && command -v apt-get`)
			if start < 0 {
				t.Fatal("missing browser bootstrap")
			}
			end := strings.Index(bootstrapScript[start:], `if [ "${CRABBOX_DOCKER_SOCKET:-0}"`)
			if end < 0 {
				t.Fatal("missing next bootstrap section")
			}
			script := "set -eu\n" + installVerifiedAPTKeyringScript + bootstrapScript[start:start+end]
			script = strings.NewReplacer("/etc/apt/", root+"/apt/", "/etc/os-release", root+"/os-release", "/usr/local/bin/crabbox-browser", root+"/unused-browser").Replace(script)
			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, "sh", "-c", script)
			actualFingerprint := fingerprint
			if tc.failure == "key" {
				actualFingerprint = strings.Repeat("A", 40)
			}
			cmd.Env = append(os.Environ(), "PATH="+bin+string(os.PathListSeparator)+os.Getenv("PATH"), "CRABBOX_BROWSER=1", "TEST_ROOT="+root, "TEST_DISTRO="+tc.distro, "TEST_AVAILABLE="+tc.available, "TEST_BROKEN="+tc.broken, "TEST_FAILURE="+tc.failure, "TEST_FINGERPRINT="+actualFingerprint)
			output, err := cmd.CombinedOutput()
			calls, _ := os.ReadFile(filepath.Join(root, "apt-calls"))
			if tc.wantError != "" {
				if err == nil || !strings.Contains(string(output), tc.wantError) || !strings.Contains(string(output), "prebuilt") {
					t.Fatalf("err=%v output=%s, want actionable %q", err, output, tc.wantError)
				}
			} else if err != nil {
				t.Fatalf("err=%v output=%s", err, output)
			}
			if tc.working != "" {
				if len(calls) != 0 {
					t.Fatalf("working browser triggered package operations: %s", calls)
				}
				if got, _ := os.ReadFile(filepath.Join(root, "working-"+tc.working)); string(got) != "original\n" {
					t.Fatal("working browser changed")
				}
			}
			if tc.wantInstall != "" && !strings.Contains(string(calls), "install -y --no-install-recommends "+tc.wantInstall+"\n") {
				t.Fatalf("missing requested install %q: %s", tc.wantInstall, calls)
			}
			if _, err := os.Stat(filepath.Join(root, "snap-attempt")); !os.IsNotExist(err) {
				t.Fatal("attempted Ubuntu Snap transition")
			}
			if tc.distro == "ubuntu" && tc.working == "" && tc.failure != "key" {
				source, _ := os.ReadFile(filepath.Join(root, "apt/sources.list.d/crabbox-mozilla.sources"))
				for _, want := range []string{"URIs: https://packages.mozilla.org/apt", "Suites: mozilla", "Architectures: arm64", "Signed-By: " + root + "/apt/keyrings/crabbox-mozilla.gpg"} {
					if !strings.Contains(string(source), want) {
						t.Fatalf("source missing %q: %s", want, source)
					}
				}
				pins, _ := os.ReadFile(filepath.Join(root, "apt/preferences.d/crabbox-mozilla"))
				if !strings.Contains(string(pins), "Package: firefox\nPin: release o=Ubuntu\nPin-Priority: -1") || strings.Contains(string(pins), "Package: *") {
					t.Fatalf("unsafe package pin: %s", pins)
				}
			}
		})
	}
}

import { once } from "node:events";
import { createServer } from "node:http";

import { afterEach, describe, expect, it, vi } from "vitest";

import type { CoordinatorStorage, CoordinatorStorageView } from "../src/coordinator-runtime";
import { sha256Hex } from "../src/encoding";
import { githubAuthRoute, githubPortalLogin } from "../src/oauth";
import type { Env } from "../src/types";

class MemoryStorage implements CoordinatorStorage {
  private readonly values = new Map<string, unknown>();

  async get<T>(key: string): Promise<T | undefined> {
    return this.values.get(key) as T | undefined;
  }

  async put<T>(key: string, value: T): Promise<void> {
    this.values.set(key, value);
  }

  async delete(key: string): Promise<void> {
    this.values.delete(key);
  }

  async list<T>({
    prefix = "",
    limit,
    startAfter,
  }: {
    prefix?: string;
    limit?: number;
    startAfter?: string;
    noCache?: boolean;
  } = {}): Promise<Map<string, T>> {
    const entries = [...this.values]
      .toSorted(([left], [right]) => left.localeCompare(right))
      .filter(([key]) => key.startsWith(prefix) && (!startAfter || key > startAfter));
    return new Map(
      (limit === undefined ? entries : entries.slice(0, limit)).map(([key, value]) => [
        key,
        value as T,
      ]),
    );
  }

  transaction<T>(callback: (transaction: CoordinatorStorageView) => Promise<T>): Promise<T> {
    return callback(this);
  }
}

function testRuntime(storage: MemoryStorage) {
  return {
    storage,
    async runExclusive<T>(callback: () => Promise<T>): Promise<T> {
      return callback();
    },
  };
}

const env = {
  CRABBOX_GITHUB_CLIENT_ID: "client-id",
  CRABBOX_GITHUB_CLIENT_SECRET: "client-secret",
  CRABBOX_GITHUB_ALLOWED_ORG: "openclaw",
  CRABBOX_DEFAULT_ORG: "openclaw",
  CRABBOX_PUBLIC_URL: "https://broker.test",
  CRABBOX_SESSION_SECRET: "session-secret",
} as Env;

function setCookies(response: Response): string[] {
  const headers = response.headers as Headers & { getSetCookie?: () => string[] };
  return headers.getSetCookie?.() ?? [headers.get("set-cookie") ?? ""];
}

function portalBindingCookie(response: Response): { name: string; pair: string } {
  const cookie = setCookies(response).find((value) =>
    value.startsWith("__Host-crabbox_oauth_state_"),
  );
  if (!cookie) throw new Error("missing portal OAuth binding cookie");
  const pair = cookie.split(";", 1)[0] ?? "";
  return { name: pair.split("=", 1)[0] ?? "", pair };
}

function oauthState(response: Response): string {
  const location = response.headers.get("location");
  if (!location) throw new Error("missing OAuth redirect");
  const state = new URL(location).searchParams.get("state");
  if (!state) throw new Error("missing OAuth state");
  return state;
}

async function startPortalLogin(storage: MemoryStorage): Promise<Response> {
  return githubPortalLogin(
    new Request("https://broker.test/portal/login"),
    testRuntime(storage),
    env,
  );
}

function stubSuccessfulGitHubOAuth(): ReturnType<typeof vi.fn> {
  const mock = vi.fn<(input: string | URL | Request) => Promise<Response>>(async (input) => {
    const url = input instanceof Request ? input.url : input.toString();
    if (url === "https://github.com/login/oauth/access_token") {
      return Response.json({ access_token: "github-access-token" });
    }
    if (url === "https://api.github.com/user") {
      return Response.json({ id: 12345, login: "alice", name: "Alice" });
    }
    if (url === "https://api.github.com/user/emails") {
      return Response.json([{ email: "alice@example.com", primary: true, verified: true }]);
    }
    if (url === "https://api.github.com/user/memberships/orgs/openclaw") {
      return Response.json({ state: "active", organization: { login: "openclaw" } });
    }
    throw new Error(`unexpected fetch ${url}`);
  });
  vi.stubGlobal("fetch", mock);
  return mock;
}

const cliPollSecret = "local-poll-secret";
const cliLoopbackRedirectURI = `http://127.0.0.1:54321/crabbox/oauth/${"a".repeat(64)}`;

async function startCLILogin(storage: MemoryStorage): Promise<{
  callbackURL: string;
  loginID: string;
}> {
  const start = await githubAuthRoute(
    new Request("https://broker.test/v1/auth/github/start", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        pollSecretHash: await sha256Hex(cliPollSecret),
        loopbackRedirectURI: cliLoopbackRedirectURI,
      }),
    }),
    "start",
    testRuntime(storage),
    env,
  );
  expect(start.status).toBe(200);
  const started = (await start.json()) as { loginID: string; url: string };
  const state = new URL(started.url).searchParams.get("state");
  expect(state).toBeTruthy();
  return {
    callbackURL: `https://broker.test/v1/auth/github/callback?code=code&state=${encodeURIComponent(state ?? "")}`,
    loginID: started.loginID,
  };
}

async function pollCLILogin(
  storage: MemoryStorage,
  loginID: string,
  browserConfirmation?: string | null,
): Promise<Response> {
  return githubAuthRoute(
    new Request("https://broker.test/v1/auth/github/poll", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        loginID,
        pollSecret: cliPollSecret,
        browserConfirmation,
      }),
    }),
    "poll",
    testRuntime(storage),
    env,
  );
}

function fetchCallCount(fetchMock: ReturnType<typeof vi.fn>, expectedURL: string): number {
  return fetchMock.mock.calls.filter(([input]) => {
    const url = input instanceof Request ? input.url : String(input);
    return url === expectedURL;
  }).length;
}

function runRetryDelayImmediately(): ReturnType<typeof vi.fn> {
  const original = globalThis.setTimeout;
  const retryDelay = vi.fn<(callback: () => void, delay: number) => number>((callback) => {
    callback();
    return 0;
  });
  vi.spyOn(globalThis, "setTimeout").mockImplementation(((
    callback: (...args: unknown[]) => void,
    delay?: number,
    ...args: unknown[]
  ) => {
    // Only collapse the OAuth retry delay; leave verification deadlines intact.
    if (delay === 200) return retryDelay(() => callback(...args), delay);
    return original(callback, delay, ...args);
  }) as typeof setTimeout);
  return retryDelay;
}

function stalledGitHubResponse(
  mode: "headers" | "body",
  value: unknown,
  status = 200,
): { response: Promise<Response>; finish: () => void } {
  let finish!: () => void;
  let finished = false;
  const response =
    mode === "headers"
      ? new Promise<Response>((resolve) => {
          finish = () => resolve(Response.json(value, { status }));
        })
      : Promise.resolve(
          new Response(
            new ReadableStream<Uint8Array>({
              start(controller) {
                const bytes = new TextEncoder().encode(JSON.stringify(value));
                controller.enqueue(bytes.slice(0, 1));
                finish = () => {
                  controller.enqueue(bytes.slice(1));
                  controller.close();
                };
              },
            }),
            { status },
          ),
        );
  return {
    response,
    finish() {
      if (!finished) {
        finished = true;
        finish();
      }
    },
  };
}

afterEach(() => {
  vi.useRealTimers();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});

describe("portal OAuth browser binding", () => {
  it("stores only a hash and sets a short-lived host cookie", async () => {
    const storage = new MemoryStorage();
    const response = await startPortalLogin(storage);

    expect(response.status).toBe(302);
    const portalCookie = portalBindingCookie(response);
    expect(portalCookie.name).toMatch(/^__Host-crabbox_oauth_state_[a-f0-9]{32}$/);
    const binding = decodeURIComponent(portalCookie.pair.split("=", 2)[1] ?? "");
    expect(binding).toMatch(/^bind_[a-f0-9]{32}$/);
    const cookie = setCookies(response).find((value) => value.startsWith(`${portalCookie.name}=`));
    expect(cookie).toContain("HttpOnly");
    expect(cookie).toContain("Secure");
    expect(cookie).toContain("SameSite=Lax");
    expect(cookie).toContain("Max-Age=600");

    const pending = [
      ...(await storage.list<{ portalBindingHash?: string }>({ prefix: "oauth:" })).values(),
    ][0];
    expect(pending?.portalBindingHash).toMatch(/^[a-f0-9]{64}$/);
    expect(pending?.portalBindingHash).not.toBe(binding);
  });

  it.each([
    ["missing", undefined],
    ["wrong", "bind_00000000000000000000000000000000"],
  ])("rejects a callback with a %s browser binding", async (_label, binding) => {
    const storage = new MemoryStorage();
    const login = await startPortalLogin(storage);
    const state = oauthState(login);
    const portalCookie = portalBindingCookie(login);
    const cookie = binding ? `${portalCookie.name}=${binding}` : undefined;
    const fetchMock = vi.fn<() => void>(() => {
      throw new Error("GitHub must not be called before browser binding passes");
    });
    vi.stubGlobal("fetch", fetchMock);

    const response = await githubAuthRoute(
      new Request(
        `https://broker.test/v1/auth/github/callback?code=code&state=${encodeURIComponent(state)}`,
        { headers: cookie ? { cookie } : undefined },
      ),
      "callback",
      testRuntime(storage),
      env,
    );

    expect(response.status).toBe(403);
    expect(fetchMock).not.toHaveBeenCalled();
    expect(setCookies(response).join("\n")).toContain(
      `${portalCookie.name}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`,
    );
    expect((await storage.list({ prefix: "oauth:" })).size).toBe(0);
  });

  it("accepts the bound browser once and clears the binding cookie", async () => {
    const storage = new MemoryStorage();
    const login = await startPortalLogin(storage);
    const state = oauthState(login);
    const portalCookie = portalBindingCookie(login);
    const fetchMock = stubSuccessfulGitHubOAuth();
    const callbackURL = `https://broker.test/v1/auth/github/callback?code=code&state=${encodeURIComponent(state)}`;

    const response = await githubAuthRoute(
      new Request(callbackURL, { headers: { cookie: portalCookie.pair } }),
      "callback",
      testRuntime(storage),
      env,
    );

    expect(response.status).toBe(302);
    expect(response.headers.get("location")).toBe("/portal");
    expect(setCookies(response).join("\n")).toContain("__Host-crabbox_session=");
    expect(setCookies(response).join("\n")).toContain(
      `${portalCookie.name}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`,
    );
    expect((await storage.list({ prefix: "oauth:" })).size).toBe(0);

    const calls = fetchMock.mock.calls.length;
    const replay = await githubAuthRoute(
      new Request(callbackURL, { headers: { cookie: portalCookie.pair } }),
      "callback",
      testRuntime(storage),
      env,
    );
    expect(replay.status).toBe(400);
    expect(fetchMock).toHaveBeenCalledTimes(calls);
  });

  it("keeps concurrent portal logins independently bound", async () => {
    const storage = new MemoryStorage();
    const firstLogin = await startPortalLogin(storage);
    const secondLogin = await startPortalLogin(storage);
    const firstCookie = portalBindingCookie(firstLogin);
    const secondCookie = portalBindingCookie(secondLogin);
    expect(firstCookie.name).not.toBe(secondCookie.name);
    const browserCookies = `${firstCookie.pair}; ${secondCookie.pair}`;
    stubSuccessfulGitHubOAuth();

    const callbacks = await Promise.all(
      (
        [
          [firstLogin, firstCookie, secondCookie],
          [secondLogin, secondCookie, firstCookie],
        ] as const
      ).map(async ([login, cookie, otherCookie]) => ({
        cookie,
        otherCookie,
        response: await githubAuthRoute(
          new Request(
            `https://broker.test/v1/auth/github/callback?code=code&state=${encodeURIComponent(oauthState(login))}`,
            { headers: { cookie: browserCookies } },
          ),
          "callback",
          testRuntime(storage),
          env,
        ),
      })),
    );
    for (const { response, cookie, otherCookie } of callbacks) {
      expect(response.status).toBe(302);
      const cookies = setCookies(response).join("\n");
      expect(cookies).toContain(`${cookie.name}=;`);
      expect(cookies).not.toContain(`${otherCookie.name}=;`);
    }
    expect((await storage.list({ prefix: "oauth:" })).size).toBe(0);
  });

  it("does not clear an unrelated binding for an unknown callback state", async () => {
    const storage = new MemoryStorage();
    const login = await startPortalLogin(storage);
    const portalCookie = portalBindingCookie(login);

    const response = await githubAuthRoute(
      new Request("https://broker.test/v1/auth/github/callback?code=code&state=unknown", {
        headers: { cookie: portalCookie.pair },
      }),
      "callback",
      testRuntime(storage),
      env,
    );

    expect(response.status).toBe(400);
    expect(setCookies(response).join("\n")).not.toContain(`${portalCookie.name}=;`);
    expect((await storage.list({ prefix: "oauth:" })).size).toBeGreaterThan(0);
  });

  it("fails closed on legacy email revocation configuration", async () => {
    const storage = new MemoryStorage();
    const login = await startPortalLogin(storage);
    stubSuccessfulGitHubOAuth();

    const response = await githubAuthRoute(
      new Request(
        `https://broker.test/v1/auth/github/callback?code=code&state=${encodeURIComponent(oauthState(login))}`,
        { headers: { cookie: portalBindingCookie(login).pair } },
      ),
      "callback",
      testRuntime(storage),
      { ...env, CRABBOX_GITHUB_REVOKED_USERS: "owner:alice@example.com" },
    );

    expect(response.status).toBe(403);
    expect(await response.text()).toContain(
      "Replace email or login selectors with github:&lt;numeric-id&gt;",
    );
  });
});

describe("GitHub OAuth transient failures", () => {
  it.each([
    { mode: "headers", status: 200 },
    { mode: "body", status: 200 },
    { mode: "body", status: 403 },
  ] as const)(
    "bounds stalled OAuth exchange $mode/$status without retrying or late credential writes",
    async ({ mode, status }) => {
      const storage = new MemoryStorage();
      const { callbackURL, loginID } = await startCLILogin(storage);
      const fetchMock = stubSuccessfulGitHubOAuth();
      vi.useFakeTimers();
      let started!: () => void;
      const entered = new Promise<void>((resolve) => {
        started = resolve;
      });
      const stalled = stalledGitHubResponse(
        mode,
        status === 200 ? { access_token: "github-access-token" } : { error: "upstream-error" },
        status,
      );
      fetchMock.mockImplementationOnce(() => {
        started();
        return stalled.response;
      });
      let callbackStatus: number | undefined;
      const callback = githubAuthRoute(
        new Request(callbackURL),
        "callback",
        testRuntime(storage),
        env,
      ).then((response) => {
        callbackStatus = response.status;
        return response;
      });
      try {
        await entered;
        await vi.advanceTimersByTimeAsync(15_000);
        expect(callbackStatus).toBe(503);
        expect(fetchMock).toHaveBeenCalledOnce();
        const pending = structuredClone(
          await storage.get<Record<string, unknown>>(`oauth:${loginID}`),
        );
        expect(pending).toMatchObject({ id: loginID });
        expect(pending?.githubCredential).toBeUndefined();
        expect(pending?.token).toBeUndefined();
        expect(pending?.callbackClaim).toBeUndefined();
